const PATCH_VERSION='loader-v9-aircraft-weapons-destruction';
const BASE_BOOTSTRAP='https://raw.githubusercontent.com/XposeMarket/Skystrike/flight-universe-pwa/bootstrap.js?v=base-v8-hd';
const UPGRADE_CODE="function upgradeAircraftWeapons(source){\n  source=source.replace('https://assets.science.nasa.gov/content/dam/science/cds/3d/resources/model/global-hawk/Global%20Hawk.glb','https://cdn.jsdelivr.net/gh/nasa/NASA-3D-Resources@master/3D%20Models/Global%20Hawk/Global%20Hawk.glb');\n  source=source.replace('https://assets.science.nasa.gov/content/dam/science/cds/3d/resources/model/space-shuttle-%28d%29/Space%20Shuttle%20%28D%29.glb','https://cdn.jsdelivr.net/gh/nasa/NASA-3D-Resources@master/3D%20Models/Space%20Shuttle%20%28D%29/Space%20Shuttle%20%28D%29.glb');\n  const destructibleTile=\"function makeBuildingTile(tx, ty, elements) {\\n  const groups = { default: [], glass: [], brick: [], industrial: [] };\\n  const colliders = [];\\n  let accepted = 0;\\n  const tileKey = `${BUILDING_ZOOM}/${tx}/${ty}`;\\n  for (const way of elements) {\\n    const buildingId = String(way.id ?? `${tileKey}:${accepted}`);\\n    if (destroyedBuildingIds.has(buildingId) || accepted >= BUILDING_TILE_LIMIT || !way.geometry || way.geometry.length < 4) continue;\\n    try {\\n      const points = way.geometry.map(point => localFromGeo(point.lat, point.lon));\\n      let area = 0, cx = 0, cz = 0;\\n      for (let i = 0; i < points.length; i++) {\\n        const a = points[i], b = points[(i + 1) % points.length];\\n        area += a.x * b.z - b.x * a.z;\\n        cx += a.x; cz += a.z;\\n      }\\n      area = Math.abs(area) * .5; cx /= points.length; cz /= points.length;\\n      if (!Number.isFinite(area) || area < 12) continue;\\n      const shape = new THREE.Shape(); shape.moveTo(points[0].x, -points[0].z);\\n      for (let i = 1; i < points.length; i++) shape.lineTo(points[i].x, -points[i].z);\\n      shape.closePath();\\n      const tags = way.tags || {}, height = parseBuildingHeight(tags, area, Number(way.id) || accepted), kind = buildingKind(tags, height);\\n      const geometry = new THREE.ExtrudeGeometry(shape, { depth: height, bevelEnabled: false, steps: 1 });\\n      geometry.rotateX(-Math.PI / 2);\\n      const base = terrainHeightAt(cx, cz) + .25;\\n      geometry.translate(0, base, 0);\\n      groups[kind].push(geometry);\\n      const minX = Math.min(...points.map(p=>p.x)), maxX = Math.max(...points.map(p=>p.x)), minZ = Math.min(...points.map(p=>p.z)), maxZ = Math.max(...points.map(p=>p.z));\\n      colliders.push({ id: buildingId, tileKey, polygon: points.map(p=>({x:p.x,z:p.z})), minX, maxX, minZ, maxZ, base, top: base + height, cx, cz, height, kind });\\n      accepted++;\\n    } catch {}\\n  }\\n  const group = new THREE.Group();\\n  group.name = `osm-buildings-${BUILDING_ZOOM}-${tx}-${ty}`;\\n  for (const [kind, geometries] of Object.entries(groups)) {\\n    if (!geometries.length) continue;\\n    const merged = new THREE.BufferGeometry(); let vertexOffset = 0;\\n    const positionArrays = [], normalArrays = [], uvArrays = [], roofIndices = [], wallIndices = [];\\n    for (const geometry of geometries) {\\n      const position=geometry.getAttribute('position'), normal=geometry.getAttribute('normal'), uv=geometry.getAttribute('uv');\\n      positionArrays.push(position.array); if(normal)normalArrays.push(normal.array); if(uv)uvArrays.push(uv.array);\\n      const index=geometry.getIndex(), localIndex=index?Array.from(index.array):Array.from({length:position.count},(_,i)=>i);\\n      if(geometry.groups?.length){\\n        for(const part of geometry.groups){const target=part.materialIndex===0?roofIndices:wallIndices;for(let i=part.start;i<part.start+part.count;i++)target.push(localIndex[i]+vertexOffset);}\\n      } else { for(const value of localIndex)wallIndices.push(value+vertexOffset); }\\n      vertexOffset += position.count; geometry.dispose();\\n    }\\n    merged.setAttribute('position',new THREE.Float32BufferAttribute(Float32Array.from(positionArrays.flatMap(a=>Array.from(a))),3));\\n    if(normalArrays.length===geometries.length)merged.setAttribute('normal',new THREE.Float32BufferAttribute(Float32Array.from(normalArrays.flatMap(a=>Array.from(a))),3));\\n    if(uvArrays.length===geometries.length)merged.setAttribute('uv',new THREE.Float32BufferAttribute(Float32Array.from(uvArrays.flatMap(a=>Array.from(a))),2));\\n    merged.setIndex([...roofIndices,...wallIndices]); merged.clearGroups();\\n    if(roofIndices.length)merged.addGroup(0,roofIndices.length,0);\\n    if(wallIndices.length)merged.addGroup(roofIndices.length,wallIndices.length,1);\\n    if(normalArrays.length!==geometries.length)merged.computeVertexNormals(); merged.computeBoundingSphere();\\n    const mesh=new THREE.Mesh(merged,[makeRoofMaterial(kind),makeBuildingMaterial(kind)]); mesh.userData.buildingCount=geometries.length; group.add(mesh);\\n  }\\n  group.userData.buildingCount=accepted;\\n  group.userData.colliders=colliders;\\n  group.userData.sourceElements=elements;\\n  group.userData.tx=tx;\\n  group.userData.ty=ty;\\n  group.add(makeVegetationTile(tx,ty,accepted));\\n  return group;\\n}\";\n  source=source.replace(/function makeBuildingTile\\(tx, ty, elements\\) \\{[\\s\\S]*?\\n\\}\\n\\nfunction parseOsmBuildingXml/,destructibleTile+'\\n\\nfunction parseOsmBuildingXml');\n  const combat=\"const destroyedBuildingIds = new Set();\\nconst buildingDamage = new Map();\\nconst weaponRoot = new THREE.Group(); scene.add(weaponRoot);\\nconst projectiles = [], combatEffects = [];\\nconst weaponState = { gunHeld:false, gunCooldown:0, rocketCooldown:0, barrel:1 };\\nfunction rafaleWeaponsReady(){ return state.currentAircraft==='rafale' && state.mode==='earth' && state.running; }\\nfunction weaponForward(){ return new THREE.Vector3(0,0,-1).applyQuaternion(flightQuat).normalize(); }\\nfunction weaponRight(){ return new THREE.Vector3(1,0,0).applyQuaternion(flightQuat).normalize(); }\\nfunction removeProjectile(i){ const p=projectiles[i]; weaponRoot.remove(p.mesh); p.mesh.traverse?.(o=>{o.geometry?.dispose?.();if(o.material){const ms=Array.isArray(o.material)?o.material:[o.material];ms.forEach(m=>m.dispose?.());}}); projectiles.splice(i,1); }\\nfunction spawnMuzzleFlash(pos){ const m=new THREE.Mesh(new THREE.SphereGeometry(.55,8,6),new THREE.MeshBasicMaterial({color:0xffe2a0,transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false}));m.position.copy(pos);weaponRoot.add(m);combatEffects.push({type:'flash',group:m,age:0,life:.08}); }\\nfunction fireBullet(){\\n  if(!rafaleWeaponsReady()){ if(state.running)toast('Weapons are available on the Rafale'); return; }\\n  const f=weaponForward(), r=weaponRight(); weaponState.barrel*=-1;\\n  const pos=flightPos.clone().addScaledVector(f,11).addScaledVector(r,weaponState.barrel*.85).add(new THREE.Vector3(0,-.25,0));\\n  const mesh=new THREE.Mesh(new THREE.BoxGeometry(.08,.08,3.2),new THREE.MeshBasicMaterial({color:0xffe9a8,blending:THREE.AdditiveBlending,depthWrite:false}));\\n  mesh.position.copy(pos); mesh.quaternion.copy(flightQuat); weaponRoot.add(mesh);\\n  projectiles.push({type:'bullet',mesh,velocity:f.multiplyScalar(940+Math.max(0,state.speed)),ttl:2.4}); spawnMuzzleFlash(pos);\\n}\\nfunction fireRocket(){\\n  if(!rafaleWeaponsReady()){ if(state.running)toast('Rockets are available on the Rafale'); return; }\\n  if(weaponState.rocketCooldown>0)return; weaponState.rocketCooldown=.72;\\n  const f=weaponForward(), r=weaponRight(), side=weaponState.barrel*=-1;\\n  const pos=flightPos.clone().addScaledVector(f,7).addScaledVector(r,side*2.7).add(new THREE.Vector3(0,-.9,0));\\n  const g=new THREE.Group(), mat=new THREE.MeshStandardMaterial({color:0xd9dde2,metalness:.55,roughness:.38});\\n  const body=new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,1.55,8),mat); body.rotation.x=Math.PI/2; g.add(body);\\n  const nose=new THREE.Mesh(new THREE.ConeGeometry(.16,.42,8),mat); nose.rotation.x=-Math.PI/2; nose.position.z=-.98; g.add(nose);\\n  const flame=new THREE.Mesh(new THREE.ConeGeometry(.12,.55,8),new THREE.MeshBasicMaterial({color:0xff9f3b,transparent:true,opacity:.95,blending:THREE.AdditiveBlending,depthWrite:false})); flame.rotation.x=Math.PI/2; flame.position.z=.98; g.add(flame);\\n  g.position.copy(pos); g.quaternion.copy(flightQuat); weaponRoot.add(g);\\n  projectiles.push({type:'rocket',mesh:g,velocity:f.multiplyScalar(315+Math.max(0,state.speed)),ttl:8,smoke:0}); toast('ROCKET AWAY');\\n}\\nfunction spawnSmoke(pos,size=.8){ const m=new THREE.Mesh(new THREE.SphereGeometry(size,7,5),new THREE.MeshBasicMaterial({color:0x555b62,transparent:true,opacity:.38,depthWrite:false}));m.position.copy(pos);weaponRoot.add(m);combatEffects.push({type:'smoke',group:m,age:0,life:1.5,drift:new THREE.Vector3((Math.random()-.5)*1.4,1.2+Math.random()*1.5,(Math.random()-.5)*1.4)}); }\\nfunction spawnExplosion(pos,power=1){\\n  const g=new THREE.Group();g.position.copy(pos);weaponRoot.add(g);\\n  const core=new THREE.Mesh(new THREE.SphereGeometry(Math.max(.6,power*.38),12,8),new THREE.MeshBasicMaterial({color:power>3?0xff9d32:0xffd27a,transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false}));\\n  const shell=new THREE.Mesh(new THREE.SphereGeometry(Math.max(1,power*.65),10,7),new THREE.MeshBasicMaterial({color:0xff5d2f,transparent:true,opacity:.7,wireframe:true,blending:THREE.AdditiveBlending,depthWrite:false}));g.add(core,shell);\\n  const sparks=[];for(let i=0,n=Math.min(34,10+Math.floor(power*4));i<n;i++){const m=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,.12),new THREE.MeshBasicMaterial({color:i%3?0xffc14d:0xff5d2f,transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false}));g.add(m);sparks.push({mesh:m,vel:new THREE.Vector3(Math.random()-.5,Math.random()*.8+.2,Math.random()-.5).normalize().multiplyScalar((5+Math.random()*13)*Math.max(1,power*.55))});}\\n  combatEffects.push({type:'explosion',group:g,core,shell,sparks,age:0,life:.85,power}); if(power>2)for(let i=0;i<4;i++)spawnSmoke(pos.clone().add(new THREE.Vector3((Math.random()-.5)*power,Math.random()*power*.35,(Math.random()-.5)*power)),Math.max(.8,power*.18));\\n}\\nfunction spawnCollapse(c){\\n  const g=new THREE.Group();weaponRoot.add(g);const pieces=[],w=Math.max(4,c.maxX-c.minX),d=Math.max(4,c.maxZ-c.minZ),h=Math.max(4,c.height),count=Math.min(34,12+Math.floor(Math.sqrt(w*d)*.45));\\n  for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.BoxGeometry(Math.max(.8,w*(.06+Math.random()*.13)),Math.max(.8,h*(.05+Math.random()*.12)),Math.max(.8,d*(.06+Math.random()*.13))),new THREE.MeshStandardMaterial({color:c.kind==='brick'?0x8f5d49:c.kind==='glass'?0x7397a4:0x777775,roughness:.85,metalness:.03,transparent:true,opacity:1}));mesh.position.set(c.minX+Math.random()*w,c.base+Math.random()*h,c.minZ+Math.random()*d);mesh.rotation.set(Math.random()*Math.PI,Math.random()*Math.PI,Math.random()*Math.PI);g.add(mesh);pieces.push({mesh,vel:new THREE.Vector3((Math.random()-.5)*12,3+Math.random()*13,(Math.random()-.5)*12),spin:new THREE.Vector3((Math.random()-.5)*5,(Math.random()-.5)*5,(Math.random()-.5)*5)});}\\n  combatEffects.push({type:'collapse',group:g,pieces,age:0,life:3.3,ground:c.base});spawnExplosion(new THREE.Vector3(c.cx,c.base+c.height*.45,c.cz),Math.min(9,3+Math.sqrt(w*d)*.08));\\n}\\nfunction rebuildDestroyedBuilding(c){ const old=buildingTileMap.get(c.tileKey);if(!old)return;const els=old.userData.sourceElements,tx=old.userData.tx,ty=old.userData.ty;if(!els)return;buildingsGroup.remove(old);disposeObject(old);const repl=makeBuildingTile(tx,ty,els);buildingTileMap.set(c.tileKey,repl);buildingsGroup.add(repl); }\\nfunction damageBuilding(c,amount,pos,explosive=false){ if(!c||destroyedBuildingIds.has(c.id))return;const next=(buildingDamage.get(c.id)||0)+amount;buildingDamage.set(c.id,next);spawnExplosion(pos,explosive?5.5:1.15);if(next<4)return;destroyedBuildingIds.add(c.id);spawnCollapse(c);rebuildDestroyedBuilding(c);toast('BUILDING COLLAPSE'); }\\nfunction updateCombat(dt){\\n  weaponState.gunCooldown=Math.max(0,weaponState.gunCooldown-dt);weaponState.rocketCooldown=Math.max(0,weaponState.rocketCooldown-dt);if(weaponState.gunHeld&&weaponState.gunCooldown<=0){fireBullet();weaponState.gunCooldown=.055;}\\n  for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.ttl-=dt;if(p.ttl<=0){removeProjectile(i);continue;}p.mesh.position.addScaledVector(p.velocity,dt);if(p.type==='rocket'){p.smoke-=dt;if(p.smoke<=0){p.smoke=.045;spawnSmoke(p.mesh.position.clone(),.42);}}if(state.mode!=='earth')continue;const hit=buildingCollisionAt(p.mesh.position.x,p.mesh.position.z,p.mesh.position.y);if(hit){damageBuilding(hit,p.type==='rocket'?5:1,p.mesh.position.clone(),p.type==='rocket');removeProjectile(i);continue;}const ground=terrainHeightAt(p.mesh.position.x,p.mesh.position.z);if(Number.isFinite(ground)&&p.mesh.position.y<=ground+1.5){spawnExplosion(new THREE.Vector3(p.mesh.position.x,ground+1,p.mesh.position.z),p.type==='rocket'?6:1);removeProjectile(i);}}\\n  for(let i=combatEffects.length-1;i>=0;i--){const e=combatEffects[i];e.age+=dt;const t=e.age/e.life;if(e.type==='flash'){e.group.scale.setScalar(1+t*3);e.group.material.opacity=1-t;}else if(e.type==='smoke'){e.group.position.addScaledVector(e.drift,dt);e.group.scale.multiplyScalar(1+dt*.7);e.group.material.opacity=.38*(1-t);}else if(e.type==='explosion'){e.core.scale.setScalar(1+t*4*e.power);e.shell.scale.setScalar(1+t*6*e.power);e.core.material.opacity=Math.max(0,1-t*1.2);e.shell.material.opacity=Math.max(0,.7-t*.75);for(const s of e.sparks){s.vel.y-=9.8*dt;s.mesh.position.addScaledVector(s.vel,dt);s.mesh.material.opacity=Math.max(0,1-t);}}else if(e.type==='collapse'){for(const p of e.pieces){p.vel.y-=18*dt;p.mesh.position.addScaledVector(p.vel,dt);p.mesh.rotation.x+=p.spin.x*dt;p.mesh.rotation.y+=p.spin.y*dt;p.mesh.rotation.z+=p.spin.z*dt;if(p.mesh.position.y<e.ground){p.mesh.position.y=e.ground;p.vel.y*=-.12;p.vel.x*=.72;p.vel.z*=.72;}if(t>.65)p.mesh.material.opacity=Math.max(0,(1-t)/.35);}}if(e.age>=e.life){weaponRoot.remove(e.group);e.group.traverse?.(o=>{o.geometry?.dispose?.();if(o.material){const ms=Array.isArray(o.material)?o.material:[o.material];ms.forEach(m=>m.dispose?.());}});combatEffects.splice(i,1);}}\\n}\\nfunction installWeaponControls(){\\n  const stack=document.querySelector('.action-stack');if(!stack||document.getElementById('gunBtn'))return;const style=document.createElement('style');style.textContent='.action-stack{display:grid!important;grid-template-columns:repeat(2,40px);gap:7px!important}.weapon-action{border-color:rgba(255,182,84,.38)!important;color:#ffd08a}.weapon-action:active,.weapon-action.firing{background:rgba(255,132,55,.2)!important;box-shadow:0 0 20px rgba(255,126,44,.3)}';document.head.appendChild(style);\\n  const gun=document.createElement('button');gun.id='gunBtn';gun.className='round-action weapon-action';gun.textContent='GUN';gun.title='Cannon · hold F';const rocket=document.createElement('button');rocket.id='rocketBtn';rocket.className='round-action weapon-action';rocket.textContent='RKT';rocket.title='Rocket · press R';stack.append(gun,rocket);\\n  const stop=()=>{weaponState.gunHeld=false;gun.classList.remove('firing')};gun.addEventListener('pointerdown',e=>{e.preventDefault();weaponState.gunHeld=true;gun.classList.add('firing')});['pointerup','pointercancel','pointerleave'].forEach(ev=>gun.addEventListener(ev,stop));rocket.addEventListener('click',fireRocket);\\n  window.addEventListener('keydown',e=>{if(e.code==='KeyF'&&!e.ctrlKey&&!e.metaKey){weaponState.gunHeld=true;gun.classList.add('firing')}if(e.code==='KeyR'&&!e.repeat&&!e.ctrlKey&&!e.metaKey)fireRocket();});window.addEventListener('keyup',e=>{if(e.code==='KeyF')stop();});\\n  const attr=document.querySelector('.attribution');if(attr&&!attr.textContent.includes('Aircraft models NASA'))attr.textContent+=' · Aircraft models NASA';\\n}\\n\";\n  source=source.replace('function updateHUD(elapsed) {',combat+'\\nfunction updateHUD(elapsed) {');\n  source=source.replace('  updateSolar(dt,elapsed);','  updateSolar(dt,elapsed);\\n  updateCombat(dt);');\n  source=source.replace('populateUI();','populateUI();\\ninstallWeaponControls();');\n  return source;\n}";
try{
  const response=await fetch(BASE_BOOTSTRAP,{cache:'no-store'});
  if(!response.ok)throw new Error(`Failed to load HD base bootstrap: ${response.status}`);
  let code=await response.text();
  code=code.replace("const VERSION = 'loader-v8-hd-terrain-facades';",`const VERSION = '${PATCH_VERSION}';`);
  if(!code.includes('function cacheBustServiceWorker'))throw new Error('Base bootstrap shape changed');
  code=code.replace('function cacheBustServiceWorker',UPGRADE_CODE+'\nfunction cacheBustServiceWorker');
  if(!code.includes('source = upgradeBuildings(source);'))throw new Error('HD upgrade hook not found');
  code=code.replace('source = upgradeBuildings(source);','source = upgradeBuildings(source);\n  source = upgradeAircraftWeapons(source);');
  const moduleUrl=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));
  try{await import(moduleUrl)}finally{URL.revokeObjectURL(moduleUrl)}
}catch(error){
  console.error('[Flight Universe v9] bootstrap failed',error);
  const loading=document.getElementById('loading'),message=String(error?.message||error);
  if(loading){loading.classList.remove('out');loading.innerHTML=`<div class=\"spinner\"></div><div>FLIGHT SYSTEMS FAILED TO LOAD</div><small>${message}</small>`;}
}
